import { NextRequest, NextResponse } from "next/server";
import { getSupabaseServerClient } from "../../../lib/supabase";

export async function GET(request: NextRequest) {
  try {
    const supabase = getSupabaseServerClient();

    if (!supabase) {
      return NextResponse.json(
        { error: "Database connection failed" },
        { status: 500 }
      );
    }

    const { data, error } = await supabase
      .from("jobs")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Supabase error:", error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ jobs: data }, { status: 200 });
  } catch (error) {
    console.error("Error fetching jobs:", error);
    return NextResponse.json(
      { error: "Failed to fetch jobs" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const supabase = getSupabaseServerClient();

    if (!supabase) {
      return NextResponse.json(
        { error: "Database connection failed" },
        { status: 500 }
      );
    }

    // Validation
    const {
      company_name,
      title,
      description,
      category,
      required,
      minimum_salary,
      maximum_salary,
      country,
      city,
      location,
      remote_available,
      skills,
      apply_url,
    } = body;

    const JOB_CATEGORIES = [
      "Frontend Development",
   "Teaching",
  "Backend Development",
  "Full Stack Development",
  "Mobile Development",
  "DevOps",
  "Data Science",
  "Machine Learning",
  "Cloud Engineering",
  "QA & Testing",
  "UI/UX Design",
  "Product Management",
  "Project Management",
  "Business Analysis",
  "Database Administration",
  "Security Engineering",
  "Technical Writing",
  "HR",
  "Sales",
  "Customer Support",
  "Digital Marketing",
  "Other",
    ];

    const errors: Record<string, string> = {};

    if (!company_name?.trim()) errors.company_name = "Company name is required";
    else if (company_name.trim().length < 2)
      errors.company_name = "Company name must be at least 2 characters";
    else if (company_name.trim().length > 100)
      errors.company_name = "Company name must not exceed 100 characters";

    if (!category?.trim()) errors.category = "Category is required";
    else if (!JOB_CATEGORIES.includes(category))
      errors.category = "Invalid job category";

    if (!title?.trim()) errors.title = "Title is required";
    if (!description?.trim()) errors.description = "Description is required";
    
    if (!minimum_salary || minimum_salary < 0)
      errors.minimum_salary = "Minimum salary must be a valid number";
    if (!maximum_salary || maximum_salary < minimum_salary)
      errors.maximum_salary = "Maximum salary must be greater than minimum";
    if (!country?.trim()) errors.country = "Country is required";
    if (!city?.trim()) errors.city = "City is required";
    if (!location?.trim()) errors.location = "Location is required";
    if (typeof remote_available !== "boolean")
      errors.remote_available = "Remote availability is required";
    if (!skills || !Array.isArray(skills) || skills.length === 0)
      errors.skills = "At least one skill is required";

    if (Object.keys(errors).length > 0) {
      return NextResponse.json({ errors }, { status: 400 });
    }

    const jobData = {
      company: company_name.trim(),
      title: title.trim(),
      description: description.trim(),
      category: category.trim(),
      requirment:required,
      salary_min: minimum_salary,
      salary_max: maximum_salary,
      country: country.trim(),
      city: city.trim(),
      location: location.trim(),
      remote: remote_available,
      skills,
      created_at: new Date().toISOString(),
      apply_link: apply_url.trim(),
    };

    const { data, error } = await supabase
      .from("jobs")
      .insert([jobData])
      .select();

    if (error) {
      console.error("Supabase error:", error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json(
      { message: "Job created successfully", job: data?.[0] },
      { status: 201 }
    );
  } catch (error) {
    console.error("Error creating job:", error);
    return NextResponse.json(
      { error: "Failed to create job" },
      { status: 500 }
    );
  }
}
